        state.identity = Some(old.clone());
        state
            .devices
            .push(switchboard::ports::remote::PairedDevice {
                id: uuid::Uuid::new_v4(),
                name: "Stale".into(),
                scope: Scope::Read,
                token_sha256: "ab".repeat(32),
                created: std::time::SystemTime::UNIX_EPOCH,
                last_seen: None,
            });
    }
