    );
    drop(port);

    // The key is there now: a restart keeps everything.
    let again = port_with(FakeHost::default(), secrets, store.clone());
    assert_eq!(
        store.state().identity.as_ref().unwrap().spki_sha256,
        fresh.spki_sha256
    );
    assert!(!again.app.core().identity_rotated());
}

